class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        text = s.replace('-', '').upper()
        if not text:
            return ''
        first = len(text) % k or k
        groups = [text[:first]]
        groups.extend(text[i:i + k] for i in range(first, len(text), k))
        return '-'.join(groups)
